def getPairs(a, n):
    visited1 = set()
    un = [0] * n
    un[n - 1] = 0
    count = 0
    for i in range(n - 1, 0, -1):
        if a[i] in visited1:
            un[i - 1] = count
        else:
            un[i - 1] = count + 1
            visited1.add(a[i])
    visited2 = set()
    answer = 0
    for i in range(n - 1):
        if a[i] in visited2:
            continue
        answer += un[i]
        visited2.add(a[i])
    return answer
